<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import { useRouter } from 'vue-router'
import { ArrowUpRight, ArrowRight, Plus, Store, Package, TrendingUp, MousePointer2, Coins, AlertTriangle, Sparkles, Download, RefreshCw, CircleCheck, ChevronRight } from 'lucide-vue-next'
import { api, auth, canWrite, isAdmin, money, number, percent, platformName, type Row } from '../api'
import { useAction, useEditor, newProduct, storeFields } from '../forms'
import FormModal from '../components/FormModal.vue'
import StatusBadge from '../components/StatusBadge.vue'
import ProductArt from '../components/ProductArt.vue'
import TrendChart from '../components/TrendChart.vue'
import EmptyState from '../components/EmptyState.vue'
const data = ref<Row | null>(null), platform = ref(''), error = ref(''), loading = ref(true)
const router = useRouter()
async function load() {
  try { data.value = await api('/workspace/dashboard' + (platform.value ? '?platform=' + platform.value : '')); error.value = '' }
  catch (err) { error.value = (err as Error).message } finally { loading.value = false }
}
const action = useAction(load), editor = useEditor(load)
const summary = computed(() => data.value?.summary || {})
const allStores = ref<Row[]>([])
async function createProduct() { try { allStores.value = await api<Row[]>('/stores'); newProduct(editor, allStores.value) } catch (err) { error.value=(err as Error).message } }
async function createDemo() { await action.run('demo', () => api('/workspace/demo-data', 'POST'), '演示链路已准备好，经营数据均为合成示例') }
onMounted(load)
</script>
<template>
  <div class="page-heading"><div><span class="eyebrow">OVERVIEW</span><h1>工作台<span class="heading-dot">.</span></h1><p>{{ auth.user?.display_name }}，今天也让好商品向前一步。</p></div><div class="heading-actions"><button class="button secondary" :disabled="!!action.busy" @click="load"><RefreshCw :size="15" />刷新</button><button v-if="canWrite()" class="button primary" @click="createProduct"><Plus :size="17" />录入商品</button></div></div>
  <div v-if="error" class="error-panel">{{ error }} <button @click="load">重新加载</button></div>
  <div v-if="loading" class="loading-panel">正在整理你的工作台…</div>
  <template v-else-if="data">
    <section class="welcome-banner"><div><span class="banner-kicker"><span class="live-dot"></span> 经营有方向，成长有迹可循</span><h2>让好商品，被更多人看见。</h2><p>把商品、创意与数据放在一起，走好每一轮运营。</p><div class="banner-actions"><RouterLink to="/products" class="button primary">进入商品池 <ArrowRight :size="15" /></RouterLink><button v-if="isAdmin()" class="text-button" :disabled="!!action.busy" @click="createDemo"><Sparkles :size="15" />{{ action.busy==='demo' ? '正在准备…' : data.has_demo_data ? '查看演示数据状态' : '一键体验演示数据' }}</button></div></div><div class="banner-illustration" aria-hidden="true"><div class="illustration-ring"></div><div class="illustration-card back"><TrendingUp :size="26" /><span>持续生长</span><svg viewBox="0 0 100 40"><path d="M0 37 20 29 35 32 55 15 72 21 100 0" fill="none" stroke="#508a73" stroke-width="3" /></svg></div><div class="illustration-card front"><ProductArt category="水具" :index="0" /><div><span>每一件好商品</span><strong>都有新的可能</strong><span class="mini-pill"><CircleCheck :size="11" />经营进行中</span></div></div><span class="illustration-spark">✳</span></div></section>
    <div class="section-toolbar"><div class="segmented"><button :class="{active:platform===''}" @click="platform='';load()">全部平台</button><button v-for="p in [{value:'taobao',label:'淘宝'},{value:'douyin',label:'抖音'},{value:'jd',label:'京东'}]" :key="p.value" :class="{active:platform===p.value}" @click="platform=p.value;load()">{{ p.label }}</button></div><span class="muted small">{{ data.period_start }} — {{ data.period_end }} · 最近 14 天</span></div>
    <div class="stats-grid"><article class="stat-card"><div class="stat-label">经营收入<span class="stat-icon sage"><TrendingUp :size="18" /></span></div><strong>{{ money(summary.revenue) }}</strong><span class="stat-description">按回填经营记录汇总</span></article><article class="stat-card"><div class="stat-label">投放花费<span class="stat-icon sand"><Coins :size="18" /></span></div><strong>{{ money(summary.spend) }}</strong><span class="stat-description">收入 / 花费 <b>{{ (summary.roi || 0).toFixed(2) }}</b></span></article><article class="stat-card"><div class="stat-label">商品点击率<span class="stat-icon blue"><MousePointer2 :size="18" /></span></div><strong>{{ percent(summary.ctr) }}</strong><span class="stat-description">{{ number(summary.clicks) }} 次点击 / {{ number(summary.impressions) }} 次曝光</span></article><article class="stat-card"><div class="stat-label">在管商品<span class="stat-icon lilac"><Package :size="18" /></span></div><strong>{{ number(summary.product_count) }}<small>件</small></strong><span class="stat-description">来自 {{ summary.store_count }} 家店铺 <span v-if="summary.low_stock_count" class="warning-inline">{{ summary.low_stock_count }} 个库存预警</span></span></article></div>
    <div v-if="data.has_demo_data" class="demo-note"><Sparkles :size="14" />当前工作区包含合成演示数据，图表仅用于体验流程。<span class="mode-pill">{{ data.mode==='demo' ? '演示生成模式' : '真实模型模式' }}</span></div>
    <div class="dashboard-middle"><section class="panel trend-panel"><div class="panel-heading"><div><h2>经营趋势</h2><p>看见每一天的积累</p></div><div class="chart-legend"><span><i class="legend-revenue"></i>收入</span><span><i class="legend-spend"></i>花费</span></div></div><TrendChart :data="data.trend" /></section><section class="panel todo-panel"><div class="panel-heading"><div><h2>待办与提醒<span class="count-pill">{{ data.low_stock.length + summary.pending_jobs }}</span></h2><p>把注意力放在下一步</p></div></div><RouterLink v-if="data.low_stock.length" :to="'/products/' + data.low_stock[0].product_id" class="todo-row"><span class="todo-icon warning"><AlertTriangle :size="17" /></span><div><strong>{{ data.low_stock.length }} 个 SKU 库存偏低</strong><small>及时核对库存，安排补货</small></div><ChevronRight :size="16" /></RouterLink><RouterLink v-if="summary.pending_jobs" :to="'/products/' + data.jobs.find((j:Row)=>['pending','running'].includes(j.job_status))?.product_id + '?tab=tasks'" class="todo-row"><span class="todo-icon sage"><Sparkles :size="17" /></span><div><strong>{{ summary.pending_jobs }} 个生成任务处理中</strong><small>前往任务页查看实时进度</small></div><ChevronRight :size="16" /></RouterLink><RouterLink to="/imports" class="todo-row"><span class="todo-icon blue"><Download :size="17" /></span><div><strong>回填最近的经营数据</strong><small>让每一轮复盘更有依据</small></div><ChevronRight :size="16" /></RouterLink><div class="todo-bottom"><span class="live-dot"></span> 素材与建议均需人工审核确认</div></section></div>
    <section class="section-block"><div class="section-title"><div><h2>我的店铺<span class="muted">{{ data.stores.length }}</span></h2><p>每一家店铺，都是新的生长空间</p></div><div class="inline-actions"><RouterLink to="/stores" class="text-button">管理店铺 <ArrowUpRight :size="15" /></RouterLink><button v-if="isAdmin()" class="button secondary small-button" @click="editor.open('创建店铺',storeFields,{platform:'taobao'},'/stores')"><Plus :size="15" />创建店铺</button></div></div><div v-if="data.stores.length" class="store-grid"><RouterLink v-for="(store,i) in data.stores" :key="store.id" :to="'/stores/' + store.id" class="store-card"><div class="store-card-top"><span class="store-avatar" :class="'store-color-' + (Number(i)%3)"><Store :size="23" /></span><span class="platform-tag" :class="store.platform">{{ platformName(store.platform) }}</span><ArrowUpRight :size="17" class="store-arrow" /></div><h3>{{ store.store_name }}</h3><p>{{ store.owner_name || '未设置负责人' }} <span>·</span> 商品运营工作空间</p><div class="store-card-bottom"><span><strong>{{ store.product_count }}</strong>在管商品</span><span :class="{ 'text-warning':store.low_stock_count }"><strong>{{ store.low_stock_count }}</strong>库存预警</span><span class="store-enter">进入店铺 <ArrowRight :size="13" /></span></div></RouterLink></div><EmptyState v-else title="从第一家店铺开始" text="创建店铺，或使用演示数据体验完整运营链路。" /></section>
    <section class="panel"><div class="panel-heading"><div><h2>关注的商品</h2><p>从建档到复盘，把每件商品经营好</p></div><RouterLink to="/products" class="text-button">全部商品 <ArrowUpRight :size="15" /></RouterLink></div><div v-if="data.products.length" class="table-wrap"><table><thead><tr><th>商品信息</th><th>所属店铺</th><th>售价</th><th>库存</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="(product,i) in data.products.slice(0,5)" :key="product.id"><td><RouterLink :to="'/products/' + product.id" class="product-cell"><ProductArt :category="product.category" :image="product.images_json?.[0]" :name="product.name" :index="Number(i)" /><div><strong>{{ product.name }}</strong><small>{{ product.category }}</small></div></RouterLink></td><td class="muted">{{ product.store_name }}</td><td class="numeric">{{ money(product.price) }}</td><td><span :class="{ 'text-warning':product.low_stock_count }">{{ product.stock_qty }} 件</span></td><td><StatusBadge :value="product.status" /></td><td><RouterLink :to="'/products/' + product.id" class="table-link">开始运营 <ArrowRight :size="14" /></RouterLink></td></tr></tbody></table></div><EmptyState v-else title="好商品，即将登场" text="录入第一件商品，开始你的第一轮运营。" /></section>
  </template>
  <FormModal v-if="editor.form" v-bind="editor.form" :saving="editor.saving" :error="editor.error" @close="editor.close" @submit="editor.save" />
</template>
